# Confirmatory corpus 4: 30 public incidents not used by v1/v2/holdout/confirm2/confirm3.
#
# Same five-sibling design as v2/holdout/confirm3. Semantic evaluation queries
# deliberately use a different Chinese phrasing from the stored semantic case,
# with only sparse technical anchors, so the pre-registered Jaccard stratum can
# actually place them in tier:hard.
param(
    [string]$MemDir = (Join-Path $PSScriptRoot "confirm4-mem"),
    [string]$Csv = (Join-Path $PSScriptRoot "confirm4-cases.csv"),
    [string]$Binary = (Join-Path $PSScriptRoot "..\rs\target\release\scx.exe"),
    [switch]$Force
)

$ErrorActionPreference = "Stop"

function Write-Utf8([string]$Path, [string]$Text) {
    [IO.File]::WriteAllText($Path, $Text, (New-Object Text.UTF8Encoding $false))
}
function CsvField([string]$Value) { return '"' + $Value.Replace('"', '""') + '"' }

if (-not (Test-Path -LiteralPath $Binary)) { throw "missing release binary: $Binary" }
if (-not (Test-Path -LiteralPath $MemDir)) { New-Item -ItemType Directory -Force -Path $MemDir | Out-Null }
$existing = @(Get-ChildItem -LiteralPath $MemDir -Force -ErrorAction SilentlyContinue)
if ($existing.Count -gt 0) {
    if (-not $Force) { throw "MemDir is not empty: $MemDir (use -Force to clear workspace-local dir)" }
    $wsRoot = (Resolve-Path -LiteralPath (Join-Path $PSScriptRoot "..")).Path
    $memAbs = (Resolve-Path -LiteralPath $MemDir).Path
    if (-not $memAbs.StartsWith($wsRoot, [System.StringComparison]::OrdinalIgnoreCase)) {
        throw "refusing to clear non-workspace dir: $memAbs"
    }
    Remove-Item -LiteralPath $memAbs -Recurse -Force
    New-Item -ItemType Directory -Force -Path $memAbs | Out-Null
}

$incidents = @(
    @{ id="cfparser"; src="https://web.archive.org/web/20211029020126/https://blog.cloudflare.com/incident-report-on-memory-leak-caused-by-cloudflare-parser-bug/"; sym="cloudflare edge parser memory leak sensitive data"; key="parser bug returned cookies tokens post bodies"; pa="a parser bug made cloudflare edge servers return uninitialized memory containing private request data"; pb="the parser defect leaked cookies tokens and form bodies from edge responses"; pc="sensitive data was exposed because a parser returned memory that had not been initialized"; pd="cookies authentication tokens and POST bodies appeared in responses from the edge"; se="Cloudflare 边缘解析器泄漏 cookie token 内存"; sf="网页请求返回了未初始化缓冲区，cookie 和 token 可能被暴露"; rc="Cloudflare 解析器缺陷使边缘服务器返回未初始化内存，暴露 cookie、认证 token、POST 表单等敏感数据"; fix="修复解析器并清理可能被泄漏的凭据" },
    @{ id="buildkitecapacity"; src="https://building.buildkite.com/outage-post-mortem-for-august-23rd-82b619a3679b"; sym="buildkite database capacity downgrade peak load"; key="database capacity cut caused cascading collapse"; pa="a database capacity downgrade meant to reduce AWS spend could not handle peak traffic"; pb="the smaller database collapsed under peak load and dependent servers failed with it"; pc="cost-driven database capacity reduction left insufficient headroom for customer peak traffic"; pd="buildkite's database ran out of capacity at peak and cascaded failures through dependent servers"; se="Buildkite 为节省 AWS 成本下调数据库容量，峰值时容量不足引发级联故障"; sf="Buildkite 为省钱降了数据库规格，高峰期扛不住，依赖服务一起崩"; rc="Buildkite 为降低 AWS 成本下调数据库容量，峰值流量下容量不足，导致依赖服务器级联崩溃"; fix="恢复数据库容量并重新评估峰值容量规划" },
    @{ id="gitlabfs"; src="https://docs.google.com/document/d/1ScqXAdb6BjhsDzCo3qdPYbt1uULzgZqPO8zHeHHarS0/preview?sle=true&hl=en&forcehl=1#heading=h.dfbilqgnc5sf"; sym="gitlab primary restart wrong filesystem outage"; key="primary locked up restarted wrong mount"; pa="the primary locked up and was restarted with the wrong filesystem"; pb="bringing the database back with the incorrect filesystem caused a global gitlab outage"; pc="a restart selected the wrong disk filesystem and every gitlab service lost its database"; pd="after the primary froze it came back on an incorrect mount and gitlab went down globally"; se="GitLab 重启后挂载错误 ext4 文件系统"; sf="机器重启时选错了磁盘分区，GitLab 的 ext4 挂载失败，整个服务起不来"; rc="GitLab 主库锁死后重启，使用了错误的 ext4 文件系统，造成全球服务中断"; fix="重新挂载正确文件系统并恢复主库" },
    @{ id="heroku2558"; src="https://status.heroku.com/incidents/2558"; sym="heroku foreign key type overflow API authorization"; key="primary key exceeded smaller data type deployments failed"; pa="a foreign key used a smaller type than its primary key and overflowed when the key grew"; pb="the overflow prevented new authorizations and deployments and led to a full heroku api outage"; pc="the foreign key could not hold the primary key value and writes for authorizations failed"; pd="new authorizations and deployments stopped until the heroku api went fully down"; se="Heroku 外键类型过小导致主键溢出，API 无法授权"; sf="主键超过字段上限后，创建授权和部署都失败，Heroku API 整体不可用"; rc="Heroku 外键使用比主键更小的数据类型，主键增长后溢出，无法创建授权与部署并导致 API 全断"; fix="修正字段类型并恢复 API" },
