    @{ id="circlecik8s"; src="https://status.circleci.com/incidents/dcqb3fykhgvg"; sym="circleci kubernetes kube proxy kubelet incompatible iptables"; key="staged cluster upgrade corrupted service routing"; pa="a staged Kubernetes upgrade left kube proxy and kubelet at incompatible versions"; pb="iptables rules became corrupted and service to service routing silently failed"; pc="the version mismatch broke proxy rule synchronization across the production cluster"; pd="pods could not reach services until every node was restarted"; se="CircleCI Kubernetes 升级 kube-proxy 与 kubelet 版本不兼容，iptables 损坏"; sf="节点组件版本不一致导致 service 路由失效，iptables 规则损坏，CircleCI 生产集群逐台重启"; rc="CircleCI Kubernetes 分阶段升级后 kube-proxy 与 kubelet 版本不兼容，iptables 规则同步失败并损坏，服务间路由中断"; fix="逐节点重启集群并统一组件版本" },
    @{ id="awslambda061323"; src="https://aws.amazon.com/message/061323/"; sym="aws lambda cell scale latent defect execution environments"; key="lambda invocation failures cascaded sts eks eventbridge"; pa="Lambda frontend scaling crossed a new cell capacity threshold and triggered a latent defect"; pb="execution environments were allocated but never used and invocations failed"; pc="the defect cascaded to STS EKS EventBridge and the AWS console"; pd="Lambda calls failed across the affected cell for several hours"; se="AWS Lambda 单 cell 扩容触发隐藏缺陷，执行环境分配但不可用"; sf="日常流量增长越过容量门槛，Lambda 调用失败并级联 STS、EKS 和 EventBridge"; rc="AWS Lambda 前端 fleet 随日常流量增长跨过单 cell 新容量阈值，触发潜在软件缺陷，执行环境分配后不可用，调用失败并级联多个服务"; fix="回滚容量变更并修复 Lambda 缺陷" },
