    @{ id="appnexus"; src="https://web.archive.org/web/20250505112812/https://medium.com/xandr-tech/2013-09-17-outage-postmortem-586b19ae4307"; sym="appnexus database update double free impression bus crash"; key="delayed bug not caught in staging"; pa="a database update revealed a double free that crashed every impression bus server"; pb="the bug needed a time delay that staging did not exercise before production"; pc="all impression bus servers crashed together after the database update"; pd="the double free was invisible in staging because the test did not wait long enough"; se="AppNexus 数据库更新触发 double free，impression bus 全部崩溃"; sf="一次 DB 变更让所有竞价展示服务器同时退出，AppNexus 才发现延迟触发的 double free"; rc="AppNexus 数据库更新触发 double free，所有 impression bus 服务器同时崩溃；该缺陷需要时间延迟才能触发，staging 未覆盖"; fix="回滚数据库更新并修复 double free" },
    @{ id="att1990"; src="https://users.csc.calpoly.edu/~jdalbey/SWE/Papers/att_collapse.html"; sym="att switch recovery race condition cascading reboot"; key="c code race hazard fifty million calls blocked"; pa="a bad line of C code introduced a race that collapsed the phone network"; pb="quickfire resumption messages after an outage triggered repeated switch reboots"; pc="the race cascaded through 114 switches and blocked over fifty million calls"; pd="each recovery message retriggered the crash and kept the network down for nine hours"; se="AT&T 交换机恢复消息触发 C 代码竞态，电话网络级联重启"; sf="计划停机后快速重连让 114 台交换机反复崩溃，五千万通话被阻断"; rc="AT&T 一行 C 代码引入竞态，计划停机后的快速恢复消息触发交换机反复重启，级联影响 114 台交换机，阻断超过五千万通话"; fix="修复竞态并限制恢复消息速率" },
    @{ id="bbcoverload"; src="https://www.bbc.co.uk/blogs/internet/entries/a37b0470-47d4-3991-82bb-a7d5b8803771"; sym="bbc online database backend overload iplayer outage"; key="database throttling broke uncached online services"; pa="an overloaded database backend began throttling requests from several bbc online services"; pb="services without local database caching timed out and then failed during the overload"; pc="the database backend could not serve the load and throttled requests across bbc online"; pd="bbc iplayer and other online services failed after uncached services exhausted their timeouts"; se="BBC Online 数据库后端过载限流，未本地缓存的服务超时失败"; sf="BBC 在线服务的数据库后端扛不住开始限流，没做本地缓存的服务接连超时，iPlayer 等长时间不可用"; rc="BBC Online 数据库后端过载并对各服务请求限流，未在本地缓存数据库响应的服务超时并最终失败"; fix="恢复数据库容量并增加本地缓存与限流保护" },
    @{ id="basecamp2018"; src="https://web.archive.org/web/20220529044310/https://m.signalvnoise.com/postmortem-on-the-read-only-outage-of-basecamp-on-november-9th-2018/"; sym="basecamp database integer limit read only"; key="primary key int32 exhausted writes blocked"; pa="a database hit its integer limit and left basecamp in read only mode"; pb="the primary key reached the int32 maximum and new writes could not be accepted"; pc="basecamp 3 stayed read only until the key type was migrated"; pd="write operations failed because an integer column ran out of range"; se="Basecamp 数据库 INT32 上限触发只读，服务长时间无法写入"; sf="主键达到 INT32 极限后 Basecamp 3 只能读不能写"; rc="Basecamp 数据库整数主键达到 INT32 上限，写入失败并进入只读模式"; fix="迁移主键类型并恢复写入" }
)

if ($incidents.Count -ne 30) { throw "expected 30 incidents, got $($incidents.Count)" }

$rows = New-Object System.Collections.ArrayList
$n = 0
function Store-Case([string]$q, [string]$evalQuery, [string]$layer, [string]$rc, [string]$fix, [string]$src) {
    $script:n++
    $log = Join-Path $env:TEMP ("scx-confirm4-{0:D3}-{1}.log" -f $script:n, [guid]::NewGuid().ToString("N"))
    $text = ("{0}`n公开复盘, 来源: {1}`n根因: {2}" -f $q, $src, $rc)
    Write-Utf8 $log $text
    $prev = $ErrorActionPreference
    $ErrorActionPreference = "Continue"
    try { $out = (& $Binary --query $q --store 1 --fix $fix --mem-dir $MemDir $log 2>&1 | Out-String) }
    finally { $ErrorActionPreference = $prev }
    if ($out -notmatch "stored case=([^\s]+) added=yes") { throw "store failed case $($script:n): $q`n$out" }
    $id = $Matches[1]
    $h = $id.Split('_')[-1]
    $note = "target=$h source=$src"
    [void]$rows.Add([pscustomobject]@{ query = $evalQuery; layer = $layer; case_id = $id; note = $note })
}

foreach ($c in $incidents) {
    Store-Case $c.sym $c.sym "literal" $c.rc $c.fix $c.src
    Store-Case $c.key $c.key "literal" $c.rc $c.fix $c.src
    Store-Case $c.pa  $c.pb  "paraphrase" $c.rc $c.fix $c.src
    Store-Case $c.pc  $c.pd  "paraphrase" $c.rc $c.fix $c.src
    Store-Case $c.se  $c.sf  "semantic" $c.rc $c.fix $c.src
}

$lines = @("query,layer,case_id,note")
foreach ($r in $rows) {
    $lines += ((@($r.query, $r.layer, $r.case_id, $r.note) | ForEach-Object { CsvField ([string]$_) }) -join ",")
}
Write-Utf8 $Csv ($lines -join "`n")

$l = @($rows | Where-Object { $_.layer -eq "literal" }).Count
$p = @($rows | Where-Object { $_.layer -eq "paraphrase" }).Count
$s = @($rows | Where-Object { $_.layer -eq "semantic" }).Count
Write-Host ("confirm4 corpus: cases={0} eval={1} literal={2} paraphrase={3} semantic={4}" -f $incidents.Count, $rows.Count, $l, $p, $s)
Write-Host "next: powershell -File scripts\holdout-build.ps1 -Csv eval-real\confirm4-cases.csv -Out eval-real\confirm4-baseline.json -JudgeBy mechanical-target-confirm4-v1 -JudgeDate 2026-10-23T00:00:00Z"
